SourceCode.Declaration:
class UPSBasePriceCalcUpdateItem
{
    NoYes                       purchPriceTransfer;
    NoYes                       salesPriceTransfer;
    NoYes                       costPriceTransfer;

    UPSBasePriceVersionId       basePriceVersionId;
    TransDate                   calcDate;
    InventSiteId                siteId;

    UPSItemBasePriceCalcTable   itemBasePriceCalcTableTmp;

}

Method.Source:
boolean allParamEmpty()
{
    // all parameters are empty
    if (!purchPriceTransfer && !costPriceTransfer && !salesPriceTransfer)
    {
        return true;
    }

    return false;
}

void initParameters(
    NoYes                       _purchPriceTransfer,
    NoYes                       _salesPriceTransfer,
    NoYes                       _costPriceTransfer,
    UPSBasePriceVersionId       _basePriceVersionId,
    TransDate                   _calcDate,
    InventSiteId                _newSiteId
    )
{
    this.parmPurchPriceTransfer(_purchPriceTransfer);
    this.parmSalesPriceTransfer(_salesPriceTransfer);
    this.parmCostPriceTransfer(_costPriceTransfer);
    this.parmBasePriceVersionId(_basePriceVersionId);
    this.parmCalcDate(_calcDate);
    this.parmSiteId(_newSiteId);
}

public TransDate parmCalcDate(TransDate _calcDate = calcDate)
{
    calcDate = _calcDate;
    return calcDate;
}

public UPSBasePriceVersionId parmBasePriceVersionId(UPSBasePriceVersionId _basePriceVersionId = basePriceVersionId)
{
    basePriceVersionId = _basePriceVersionId;
    return basePriceVersionId;
}

public NoYes parmPurchPriceTransfer(NoYes _purchPriceTransfer = purchPriceTransfer)
{
    purchPriceTransfer = _purchPriceTransfer;
    return purchPriceTransfer;
}

public NoYes parmSalesPriceTransfer(NoYes _salesPriceTransfer = salesPriceTransfer)
{
    salesPriceTransfer = _salesPriceTransfer;
    return salesPriceTransfer;
}

public NoYes parmCostPriceTransfer(NoYes _costPriceTransfer = costPriceTransfer)
{
    costPriceTransfer = _costPriceTransfer;
    return costPriceTransfer;
}

public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;
    return siteId;
}

public void run()
{
    #OCCRetryCount
    InventTable inventTable;
    setprefix(UPSBasePriceCalcUpdateItem::description());

    try
    {
        if (!this.validate())
        {
            throw Exception::Error;
        }

        if (this.allParamEmpty())
        {
            return;
        }

        ttsbegin;

        while select itemBasePriceCalcTableTmp
        {
            inventTable = InventTable::find(itemBasePriceCalcTableTmp.ItemId);

            if (purchPriceTransfer)
            {
                this.updateItemBasePrice(inventTable, UPSBasePriceType::BasePricePurchase);
            }

            if (salesPriceTransfer)
            {
                this.updateItemBasePrice(inventTable, UPSBasePriceType::BasePriceSales);
            }

            if (costPriceTransfer)
            {
                this.updateItemBasePrice(inventTable, UPSBasePriceType::BasePriceInventoryCost);
            }
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        throw error("@SYS18447");
    }
}

boolean validate(Object _calledFrom = null)
{
    // no calculation data for transfer
    if (!itemBasePriceCalcTableTmp)
    {
        return checkFailed("@SYS95181");
    }

    return true;
}

void updateItemBasePrice(InventTable _inventTable , UPSBasePriceType _basePriceType)
{
    UPSItemBasePriceSim         itemBasePriceSim;
    UPSItemBasePriceCalcTrans   itemBasePriceCalcTrans;

    select firstonly itemBasePriceCalcTrans
            order by CreatedDateTime desc
            where itemBasePriceCalcTrans.PriceCalcId == itemBasePriceCalcTableTmp.PriceCalcId &&
                  itemBasePriceCalcTrans.FinalPrice  == NoYes::Yes &&
                  itemBasePriceCalcTrans.PriceType   == _basePriceType;

    if (itemBasePriceCalcTrans)
    {
        itemBasePriceSim = UPSItemBasePriceSim::find(
                            itemBasePriceCalcTableTmp.ItemId,
                            basePriceVersionId,
                            calcDate,
                            _basePriceType,
                            itemBasePriceCalcTableTmp.UnitId,
                            itemBasePriceCalcTableTmp.InventDimId,
                            siteId,
                            true);

        if (itemBasePriceSim)
        {
            this.updateItemBasePriceSim(itemBasePriceSim, itemBasePriceCalcTrans);
        }
        else
        {
            itemBasePriceSim.initFromCalcTable(itemBasePriceCalcTableTmp);

            itemBasePriceSim.PriceType   = _basePriceType;
            itemBasePriceSim.FromDate    = calcDate;
            itemBasePriceSim.PriceQty    = 1.00;
            itemBasePriceSim.Price       = itemBasePriceCalcTrans.CalculatedPrice;
            itemBasePriceSim.PriceCalcId = itemBasePriceCalcTableTmp.PriceCalcId;
            itemBasePriceSim.Calculated  = NoYes::Yes;

            itemBasePriceSim.write();
        }
    }

}

void updateItemBasePriceSim(UPSItemBasePriceSim itemBasePriceSim, UPSItemBasePriceCalcTrans _itemBasePriceCalcTrans)
{
    itemBasePriceSim.PriceCalcId = _itemBasePriceCalcTrans.PriceCalcId;
    itemBasePriceSim.Price = _itemBasePriceCalcTrans.CalculatedPrice;
    itemBasePriceSim.update();
}

static UPSBasePriceCalcUpdateItem construct()
{
    UPSBasePriceCalcUpdateItem   basePriceCalcUpdateItem;

    basePriceCalcUpdateItem = new UPSBasePriceCalcUpdateItem();

    return basePriceCalcUpdateItem;
}
